    .header {
        padding: 32px;
        border-bottom: 1px solid black;
        display: flex;
        flex-direction: row;
        justify-content: center;
        align-items: center;

        .progress-bar {
            width: 300px;
            height: 24px;
            border: 1px solid #999;
            border-radius: 12px;
            background: white;
            overflow: hidden;

            .progress-fill {
                height: 100%;
                background: palegreen;
            }
        }
    }

    .card-container {
        flex: 1;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        background: #fcfcfc;
        overflow: hidden;

        .card {
            background: white;
            display: flex;
            flex-direction: column;

            .card-header {
                border-bottom: 1px solid black;
                padding: 24px;

                h1 {
                    font-size: 36px;
                }
            }

            .card-content {
                flex: 1;
                display: flex;
                flex-direction: column;
                overflow-x: hidden;
                overflow-y: auto;

                .question,
                .answer,
                .prompt {
                    padding: 24px;
