args.command:
mkdir -p /tmp/gotest && cd /tmp/gotest && cat > main.go <<'EOF'
package main

/*
#cgo LDFLAGS: /usr/lib/x86_64-linux-gnu/libsqlite3.so.0
#include <stdlib.h>

typedef struct sqlite3 sqlite3;
typedef struct sqlite3_stmt sqlite3_stmt;
extern int sqlite3_open(const char*, sqlite3**);
extern int sqlite3_exec(sqlite3*, const char*, void*, void*, char**);
extern int sqlite3_close(sqlite3*);
*/
import "C"
import "fmt"

func main() {
	var db *C.sqlite3
	rc := C.sqlite3_open(C.CString("/tmp/gotest/t.db"), &db)
	fmt.Println("open rc:", rc)
	C.sqlite3_exec(db, C.CString("CREATE TABLE IF NOT EXISTS t(x)"), nil, nil, nil)
	C.sqlite3_close(db)
	fmt.Println("ok")
}
EOF
go mod init t >/dev/null 2>&1; go build -o t . && ./t && ls -la t.db

